function extractProducts() {
  const items = document.querySelectorAll('[data-component-type="s-search-result"]');
  const products = [];
  items.forEach((item, index) => {
    const titleEl = item.querySelector('h2');
    const title = titleEl ? titleEl.textContent.trim() : '';
    const priceEl = item.querySelector('.a-price .a-offscreen');
    const price = priceEl ? priceEl.textContent.trim() : 'N/A';
    const linkEl = item.querySelector('a.a-link-normal.s-link-style, h2 a');
    const href = linkEl ? linkEl.getAttribute('href') : '';
    const url = href.startsWith('http') ? href : 'https://www.amazon.com' + href;
    const shippingEl = item.querySelector('[aria-label*="delivery"], [aria-label*="shipping"]');
    const shippingText = shippingEl ? shippingEl.textContent.trim() : '';
    products.push({index, title, price, url, shippingText});
  });
  return products;
}
return extractProducts();

function extractProducts() {
  const items = document.querySelectorAll('[data-component-type="s-search-result"]');
  const products = [];
  items.forEach((item, index) => {
    const titleEl = item.querySelector('h2');
    const title = titleEl ? titleEl.textContent.trim() : '';
    const priceEl = item.querySelector('.a-price .a-offscreen');
    const price = priceEl ? priceEl.textContent.trim() : 'N/A';
    const linkEl = item.querySelector('h2 a');
    const href = linkEl ? linkEl.getAttribute('href') : '';
    const url = href.startsWith('http') ? href : 'https://www.amazon.com' + href;
    const deliveryText = item.textContent.match(/FREE delivery[^.]*|Get it by[^.]*|FREE Shipping[^.]*/i);
    products.push({index, title: title.substring(0,150), price, delivery: deliveryText ? deliveryText[0] : 'unknown'});
  });
  return products;
}
return JSON.stringify(extractProducts(), null, 2);

function extractProducts() {
